import{_ as t,o as a,c as r,ag as o}from"./chunks/framework.Ccn6roXv.js";const p=JSON.parse('{"title":"6. Trust boundaries","description":"Where trust changes in a TanStack Start server function request.","frontmatter":{"title":"6. Trust boundaries","description":"Where trust changes in a TanStack Start server function request."},"headers":[],"relativePath":"guide/06-trust-boundaries.md","filePath":"guide/06-trust-boundaries.md"}'),s={name:"guide/06-trust-boundaries.md"};function i(n,e,d,u,l,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="trust-boundaries" tabindex="-1">Trust boundaries <a class="header-anchor" href="#trust-boundaries" aria-label="Permalink to &quot;Trust boundaries&quot;">​</a></h1><p>A trust boundary is a place where data moves from one trust level to another.</p><p>Server functions have a clear boundary: the browser sends data, and the server receives it.</p><h2 id="main-boundaries" tabindex="-1">Main boundaries <a class="header-anchor" href="#main-boundaries" aria-label="Permalink to &quot;Main boundaries&quot;">​</a></h2><p>There are three useful boundaries to track.</p><h2 id="browser-to-network" tabindex="-1">Browser to network <a class="header-anchor" href="#browser-to-network" aria-label="Permalink to &quot;Browser to network&quot;">​</a></h2><p>Anything in browser memory can be changed by the user.</p><p>Client-side validation, hidden fields, disabled buttons, and TypeScript types are not security controls.</p><h2 id="network-to-framework" tabindex="-1">Network to framework <a class="header-anchor" href="#network-to-framework" aria-label="Permalink to &quot;Network to framework&quot;">​</a></h2><p>The framework receives bytes and tries to deserialize them.</p><p>This step protects the framework&#39;s own assumptions. It does not prove that the resulting application value is safe.</p><h2 id="framework-to-application-handler" tabindex="-1">Framework to application handler <a class="header-anchor" href="#framework-to-application-handler" aria-label="Permalink to &quot;Framework to application handler&quot;">​</a></h2><p>The application receives <code>data</code> and sometimes <code>context</code>.</p><p>This is where developer choices matter most. The handler must not treat client-influenced values as server facts.</p><h2 id="context-is-not-always-authority" tabindex="-1">Context is not always authority <a class="header-anchor" href="#context-is-not-always-authority" aria-label="Permalink to &quot;Context is not always authority&quot;">​</a></h2><p>Some frameworks let requests carry context-like values through middleware or serialized calls.</p><p>Treat request-carried context as input unless you can prove it was created on the server from a trusted session.</p><p>Roles, tenant IDs, account IDs, and permissions should come from server-side authority, not client-provided objects.</p><h2 id="security-property" tabindex="-1">Security property <a class="header-anchor" href="#security-property" aria-label="Permalink to &quot;Security property&quot;">​</a></h2><p>The property to preserve is authority separation:</p><ul><li>Identity comes from authenticated server state.</li><li>Authorization comes from server policy.</li><li>Request data describes what the user wants, not what the user is allowed to do.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p>Next, connect trust boundaries to validation and parsing.</p>',23)])])}const m=t(s,[["render",i]]);export{p as __pageData,m as default};
